using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Threading.Tasks;using UnityEngine;using UnityEngine.AI;using FireSafety;
public static class TestSchoolCrowd {public static async Task<string> Run(){Application.runInBackground=true;var s=TrainingSession.Instance;var c=UnityEngine.Object.FindAnyObjectByType<SchoolEvacuationController>();var samples=new List<object>();s.MainMenu();s.ChooseMode(TrainingMode.FireExtinguisher);s.StartSimulation();double start=Time.realtimeSinceStartupAsDouble;while(Time.realtimeSinceStartupAsDouble-start<32&&c.ArrivedCount<11){await Task.Delay(500);if(!s.Playing&&s.Page=="Pause")s.Resume();samples.Add(new{t=Time.realtimeSinceStartupAsDouble-start,arrived=c.ArrivedCount,door=c.exit.IsPassable,positions=c.people.Select(p=>new{p.name,pos=p.transform.position.ToString(),p.Arrived,p.PathFailed,remaining=p.GetComponent<NavMeshAgent>().remainingDistance}).ToArray()});}var result=new{mode=s.Mode,arrived=c.ArrivedCount,sprinklers=s.simulation.ActiveSprinklers,playerCompleted=s.evacuation.Completed,samples};var json=Newtonsoft.Json.JsonConvert.SerializeObject(result,Newtonsoft.Json.Formatting.Indented);File.WriteAllText(Path.GetFullPath("../Documentation/SchoolCrowdFirstTest.json"),json);return json;}}
